    {
        return employees
            .OrderByDescending(e => e.Salary)
            .ThenBy(e => e.Name, StringComparer.Ordinal)
            .GroupBy(e => e.Department)
            .Select(g => g.OrderByDescending(e => e.Name, StringComparer.Ordinal))
            .SelectMany(g => first(g))
            .ToList();
    }

    private static List<string> first(List<Employee> employees)
    {
        return employees
            .OrderByDescending(e => e.Salary)
            .ThenBy(e => e.Name, StringComparer.Ordinal)
            .Select(e => e.Name)
            .ToList();
    }
}

