public static class Solution
{
    public static double AveragePositive(List<double> nums)
    {
        double sum = 0.0;
        int count = 0;
        foreach (double num in nums)
        {
            if (num > 0.0)
            {
                sum += num;
                count++;
            }
        }
        if (count == 0)
        {
            return 0.0;
        }
        return sum / count;
    }
}

