{
    public static Product? FindBySku(IEnumerable<Product> products, string sku)
    {
        foreach (Product product in products)
        {
            if (product.Sku == sku)
            {
                return product;
            }
        }
        return null;
    }

    public static Dictionary<string, decimal> TotalByCategory(IEnumerable<Product> products)
    {
        var totals = new Dictionary<string, decimal>();
        foreach (Product product in products)
        {
            if (product.Category != null)
            {
                if (!totals.ContainsKey(product.Category))
                {
                    totals[product.Category] = 0m;
                }
                totals[product.Category] += product.Price;
            }
        }
        return totals;
    }
}

